const e=[{slug:"pay-per-call-leads",icon:"phone",title:"Pay-Per-Call Leads",text:"Verified inbound phone inquiries routed straight to your internal sales team with zero billable guesswork.",detail:"Turn high-intent search demand into real conversations. We build targeted campaigns, qualify calls against agreed criteria, and route the right enquiries directly to your team.",outcomes:["A clear definition of a billable, qualified call before campaigns launch","Campaign targeting aligned to your service area and customer profile","Direct call routing with tracking for source and quality","Regular reporting that shows what is working and where to improve"],process:[{title:"Agree the fit",text:"Set your ideal caller profile, coverage area, hours, and qualification rules."},{title:"Launch with tracking",text:"Put focused campaigns and call routing in place with attribution from day one."},{title:"Review quality",text:"Use call outcomes and agreed criteria to refine targeting and improve value."}],bullets:["Verified inbound calls from targeted campaigns","Calls routed directly to your sales team","Call tracking and clear reporting","Pay only for calls that meet agreed criteria"]},{slug:"custom-web-engineering",icon:"web",title:"Custom Web Engineering",text:"Fast, secure, custom-built websites and platforms engineered around your commercial goals.",detail:"Build a digital experience around how your business actually wins work. From a focused marketing site to a connected platform, we prioritise speed, clarity, accessibility, and dependable delivery.",outcomes:["A mobile-first experience shaped around customer tasks and business goals","Fast, accessible pages with a maintainable technical foundation","Useful integrations for CRM, analytics, forms, and call tracking","A practical launch and support plan, not a hand-off and goodbye"],process:[{title:"Map the experience",text:"Clarify your audience, journeys, content, and measurable conversion goals."},{title:"Design and build",text:"Create and test a responsive experience with performance and accessibility in mind."},{title:"Launch and improve",text:"Deploy with tracking in place, then use real usage to guide improvements."}],bullets:["Custom-built, mobile-first websites","Fast load times and strong performance scores","Secure hosting, backups and maintenance","Integrations with your CRM and call tracking"]},{slug:"it-infrastructure",icon:"shield",title:"IT Infrastructure",text:"Hands-on UK technical support and secure cloud management keeping your daily operational systems resilient.",detail:"Keep the systems your team depends on secure, supported, and ready for change. Get practical help with everyday issues alongside proactive infrastructure care.",outcomes:["A responsive helpdesk with clear ownership and useful updates","Practical cloud, device, and account management","Monitoring, patching, backup checks, and continuity planning","A prioritised improvement plan that fits your team and risk profile"],process:[{title:"Understand your setup",text:"Review your systems, users, pain points, and operational priorities."},{title:"Stabilise and support",text:"Resolve urgent issues, document essentials, and establish a reliable support route."},{title:"Improve continuously",text:"Track recurring issues and make measured improvements to resilience and security."}],bullets:["Hands-on UK helpdesk and technical support","Secure cloud setup and management","Monitoring, patching and backups","Fast response times on every ticket"]}],a=[{value:"14,500+",label:"Verified phone leads"},{value:"99.95%",label:"Managed platform uptime"},{value:"<15 mins",label:"Average IT response"}],t=[{color:"orange",title:"Transparent by default",text:"Clear scope, clear pricing and clear reporting. You always know what you are paying for and what it delivers."},{color:"pink",title:"Pay for real conversations",text:"Our pay-per-call model means you invest in verified, qualified inbound calls — not clicks or guesswork."},{color:"purple",title:"UK-based support",text:"Hands-on technical help from a team based in London, with remote coverage for international clients."},{color:"blue",title:"One accountable partner",text:"Lead generation, web engineering and IT support under one roof, so nothing falls between suppliers."}],i=[{title:"Discovery call",text:"We learn your goals, current setup and sales process in a focused, no-pressure conversation."},{title:"Scope & proposal",text:"You receive a clear scope, transparent pricing and agreed success measures. No hidden extras."},{title:"Launch",text:"We switch on call routing, build your platform or onboard your systems, and keep you updated."},{title:"Measure & improve",text:"Regular reporting on calls, uptime and response times, with practical next steps."}],n=[{name:"Priya Shah",company:"Northgate Home Services",image:"/images/avatar-priya.jpg",quote:"The calls we receive are genuinely qualified. Our sales team now spends its time closing, not chasing."},{name:"Daniel Reeves",company:"Harlow & Reeves Legal",image:"/images/avatar-daniel.jpg",quote:"Their IT team responds as quickly as promised, and our new website loads in a flash. Dependable from day one."},{name:"Sophie Clarke",company:"Brightwell Logistics",image:"/images/avatar-sophie.jpg",quote:"One partner for leads, web and IT support has simplified how we work. Clear reporting and no surprises."}],s=[{slug:"verify-calls-before-you-spend",title:"How to verify calls before you spend on lead generation",excerpt:"A practical framework for measuring inbound quality and making smarter marketing decisions.",image:"/images/hero-team.jpg",date:"12 Aug 2025",read:"4 min read",tag:"Strategy",introduction:"A ringing phone is not automatically a good lead. Before investing in call generation, agree what a useful conversation looks like, how it will be measured, and what happens when a call does not meet the brief.",sections:[{heading:"Define a qualified call before launch",paragraphs:["Start with the customer you can genuinely help. Write down the service requested, the locations you cover, the hours you can answer, and any minimum requirements. Keep the definition specific enough to apply consistently.","Agree practical exclusions too: wrong-number calls, existing-customer support, sales solicitations, and calls outside your service area may need different treatment."]},{heading:"Measure outcomes, not just volume",paragraphs:["Call volume is a useful activity measure, but it does not tell you whether the campaign is creating commercial value. Track answer rate, qualified-call rate, missed calls, and the next step taken by your team.","Use a shared reporting window and a consistent call-review process. This helps separate genuine campaign issues from short-term changes in availability or sales follow-up."]},{heading:"Close the feedback loop",paragraphs:["Give the campaign team timely, structured feedback on call quality. A short outcome code and a note about the reason for rejection are far more actionable than a general impression.","Review the criteria together as the business learns. The goal is not to move the goalposts after the fact, but to make the original agreement more accurate with evidence."],points:["Keep qualification rules visible to marketing and sales","Review a representative sample of calls","Record missed-call and follow-up outcomes","Agree changes before applying them to billing or reporting"]}],takeaway:"Good call measurement makes expectations clear for everyone: the campaign team, the sales team, and the people paying for growth."},{slug:"build-a-site-that-converts",title:"What a conversion-focused website should do for service businesses",excerpt:"Design, messaging and tracking choices that help your site turn attention into booked calls.",image:"/images/why-ringstack.jpg",date:"28 Jul 2025",read:"5 min read",tag:"Web",introduction:"A business website should make it easy for the right customer to understand your offer and take the next step. A conversion-focused site is not a collection of tricks; it is a clear, dependable experience built around user intent.",sections:[{heading:"Make the value easy to understand",paragraphs:["Visitors should quickly see who you help, what problem you solve, and why your approach is credible. Use concrete language that reflects the questions customers actually ask.","Give each important audience a clear path. If every service and audience competes for the same headline and call to action, the page becomes harder to use."]},{heading:"Remove friction from the next step",paragraphs:["Make contact options visible and predictable. Forms should ask only for information needed to respond, while phone links and booking actions should work cleanly on mobile.","Use page structure to support a decision: explain the offer, answer likely concerns, establish trust, and then repeat a relevant next step."]},{heading:"Treat performance as part of the experience",paragraphs:["Slow pages, broken layouts, and inaccessible controls undermine trust. Build around responsive layouts, compressed assets, semantic structure, and keyboard-friendly interactions from the start.","After launch, measure useful actions rather than vanity metrics. Combine analytics with customer feedback and sales outcomes to prioritise the next improvement."],points:["A clear message for a defined audience","Fast, mobile-first layouts","Accessible and predictable navigation","Reliable conversion tracking and ongoing iteration"]}],takeaway:"The best conversion improvements usually come from making the right action clearer and the experience around it more dependable."},{slug:"keep-it-support-from-derailing-growth",title:"Keeping IT support resilient without slowing down your sales team",excerpt:"The infrastructure habits that protect uptime while preserving momentum across the business.",image:"/images/avatar-priya.jpg",date:"07 Jun 2025",read:"3 min read",tag:"IT",introduction:"When everyday technology gets in the way, the impact spreads quickly: interrupted customer service, delayed work, and avoidable risk. Reliable IT support combines a helpful response when things go wrong with steady work to prevent repeat problems.",sections:[{heading:"Give people a clear route to help",paragraphs:["Staff should know where to raise an issue, what information helps, and when they can expect an update. Acknowledgement and ownership matter, even when a full fix takes longer.","Simple priority definitions help the team distinguish a business-wide outage from a routine request without making every ticket feel urgent."]},{heading:"Prevent repeat interruptions",paragraphs:["Look for patterns in recurring incidents. A repeated access problem, unstable device, or unreliable process often deserves a root-cause fix rather than another quick reset.","Keep core systems maintained with appropriate patching, tested backups, documented access, and monitoring that reaches someone able to act."]},{heading:"Make resilience a routine",paragraphs:["Resilience is not a single product or emergency document. It is a set of small, maintained practices that reduce the chance and impact of disruption.","Review the most important business services regularly: who owns them, how they are recovered, and what your team should do if they are unavailable."],points:["Clear support ownership and escalation","Routine patching and account access reviews","Backups with recovery checks","A short, usable continuity plan for critical systems"]}],takeaway:"Responsive support solves today’s issue; good operational practice makes tomorrow’s interruption less likely."}],r=[{q:"How does pay-per-call lead generation work?",a:"We run targeted campaigns that drive inbound phone calls to your sales team. Each call is verified against agreed criteria, and you only pay for calls that meet them."},{q:"What counts as a verified call?",a:"A verified call meets the criteria we agree up front, such as a minimum call length, a relevant enquiry and a caller in your service area."},{q:"Do you support businesses outside the UK?",a:"Our IT support is UK-focused, but we work with international clients remotely on lead generation and web engineering."},{q:"How quickly can we get started?",a:"After a discovery call and an agreed scope, most projects begin within one to two weeks."}];export{i as a,a as b,r as f,s as p,t as r,e as s,n as t};
